sub(p,'export async function updateProject(','''/**
 * Clones a project into the same workspace (ADR 0012). Every gate runs before
 * the first write so a refused clone leaves nothing behind; the clone is
 * announced by one `project.cloned`, never by `project.created` or per-issue
 * `issue.created`.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const toCopy = input.includeIssues
    ? await issueRepo.countIssues(input.orgId, source.id)
    : 0;
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, toCopy)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.slug);
  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const parsedStatus = issueStatusSchema.safeParse(
    org.settings.defaultIssueStatus,
  );
  const issuesCopied = input.includeIssues
    ? await issueRepo.cloneLiveIssues(
        input.orgId,
        source.id,
        project.id,
        actor.userId,
        parsedStatus.success ? parsedStatus.data : "backlog",
      )
    : 0;

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

